<?php
require __DIR__.'/../app/bootstrap.php';
require_once __DIR__.'/../app/api_v2.php';
$admin=require_permission('mobile_api.manage');$msg=$err=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{csrf_check();$a=(string)($_POST['action']??'');
        if($a==='save_settings'){
            save_settings([
                'mobile_api_v2_enabled'=>isset($_POST['mobile_api_v2_enabled'])?'1':'0',
                'customer_app_enabled'=>isset($_POST['customer_app_enabled'])?'1':'0',
                'seller_app_enabled'=>isset($_POST['seller_app_enabled'])?'1':'0',
                'mobile_app_maintenance'=>isset($_POST['mobile_app_maintenance'])?'1':'0',
                'customer_app_name'=>trim((string)($_POST['customer_app_name']??'ShahkotPK')),
                'seller_app_name'=>trim((string)($_POST['seller_app_name']??'ShahkotPK Seller')),
                'customer_app_package'=>trim((string)($_POST['customer_app_package']??'')),
                'seller_app_package'=>trim((string)($_POST['seller_app_package']??'')),
                'mobile_access_token_days'=>(string)max(1,min(30,(int)($_POST['mobile_access_token_days']??7))),
                'mobile_refresh_token_days'=>(string)max(7,min(365,(int)($_POST['mobile_refresh_token_days']??90))),
                'mobile_api_rate_limit_per_minute'=>(string)max(30,min(1200,(int)($_POST['mobile_api_rate_limit_per_minute']??120))),
                'mobile_app_support_url'=>trim((string)($_POST['mobile_app_support_url']??'/support.php')),
                'mobile_deep_link_base'=>trim((string)($_POST['mobile_deep_link_base']??'https://shahkotpk.com')),
                'mobile_seller_products_write_enabled'=>isset($_POST['mobile_seller_products_write_enabled'])?'1':'0',
                'mobile_seller_orders_write_enabled'=>isset($_POST['mobile_seller_orders_write_enabled'])?'1':'0',
                'mobile_seller_inventory_write_enabled'=>isset($_POST['mobile_seller_inventory_write_enabled'])?'1':'0',
                'mobile_seller_payout_request_enabled'=>isset($_POST['mobile_seller_payout_request_enabled'])?'1':'0',
            ]);$msg='Mobile App & Seller App settings saved.';
        }elseif($a==='save_release'){
            $app=in_array($_POST['app_type']??'customer',['customer','seller'],true)?$_POST['app_type']:'customer';$platform=in_array($_POST['platform']??'android',['android','ios'],true)?$_POST['platform']:'android';$version=trim((string)($_POST['version_name']??''));$build=max(1,(int)($_POST['build_number']??1));if($version==='')throw new RuntimeException('Version name is required.');$status=in_array($_POST['status']??'active',['draft','active','retired'],true)?$_POST['status']:'active';if($status==='active')db()->prepare("UPDATE mobile_app_releases SET status='retired' WHERE app_type=? AND platform=? AND status='active'")->execute([$app,$platform]);db()->prepare("INSERT INTO mobile_app_releases(app_type,platform,version_name,build_number,min_supported_version,force_update,store_url,release_notes,status,published_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,IF(?='active',NOW(),NULL),?)")->execute([$app,$platform,$version,$build,trim((string)($_POST['min_supported_version']??''))?:null,!empty($_POST['force_update'])?1:0,trim((string)($_POST['store_url']??''))?:null,trim((string)($_POST['release_notes']??''))?:null,$status,$status,(int)$admin['id']]);$msg='App release saved.';
        }elseif($a==='revoke_access'){
            db()->prepare('UPDATE mobile_api_tokens SET revoked_at=NOW() WHERE id=?')->execute([(int)$_POST['id']]);$msg='Access token revoked.';
        }elseif($a==='disable_device'){
            db()->prepare('UPDATE mobile_app_devices SET status=0 WHERE id=?')->execute([(int)$_POST['id']]);$msg='Device disabled.';
        }
    }catch(Throwable $e){$err=$e->getMessage();}
}
$stats=['devices'=>0,'seller_devices'=>0,'customer_devices'=>0,'tokens'=>0,'events'=>0];
try{$stats['devices']=(int)db()->query('SELECT COUNT(*) FROM mobile_app_devices WHERE status=1')->fetchColumn();$stats['seller_devices']=(int)db()->query("SELECT COUNT(*) FROM mobile_app_devices WHERE status=1 AND app_type='seller'")->fetchColumn();$stats['customer_devices']=(int)db()->query("SELECT COUNT(*) FROM mobile_app_devices WHERE status=1 AND app_type='customer'")->fetchColumn();$stats['tokens']=(int)db()->query('SELECT COUNT(*) FROM mobile_api_tokens WHERE revoked_at IS NULL AND (expires_at IS NULL OR expires_at>NOW())')->fetchColumn();$stats['events']=(int)db()->query("SELECT COUNT(*) FROM mobile_app_events WHERE created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)")->fetchColumn();}catch(Throwable $e){}
$releases=[];$devices=[];$tokens=[];$events=[];
try{$releases=db()->query('SELECT r.*,u.name creator_name FROM mobile_app_releases r LEFT JOIN users u ON u.id=r.created_by ORDER BY r.id DESC LIMIT 50')->fetchAll();}catch(Throwable $e){}
try{$devices=db()->query('SELECT d.*,u.name,u.email FROM mobile_app_devices d JOIN users u ON u.id=d.user_id ORDER BY d.last_seen_at DESC LIMIT 100')->fetchAll();}catch(Throwable $e){}
try{$tokens=db()->query('SELECT t.*,u.name,u.email FROM mobile_api_tokens t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 80')->fetchAll();}catch(Throwable $e){}
try{$events=db()->query('SELECT e.*,u.name FROM mobile_app_events e LEFT JOIN users u ON u.id=e.user_id ORDER BY e.id DESC LIMIT 50')->fetchAll();}catch(Throwable $e){}
require __DIR__.'/../app/layout.php';page_start('Mobile App & Seller App',true);
